{
  "journeyId": "{{ij_mg_journey_id}}",
  "order": 1,
  "name": "MG NetOff daily",
  "description": "Single MG milestone: NetOffEarnings. evaluation.logic is ridesCompleted>=0 AND (acceptanceRate>=0 OR onlineMinutes>=0) for UI/bag-eval shape; NetOff settle does not gate on it \u2014 payout max(0,(MG-earnings)*minPercent/100) from rewardMetadata slabs (onlineMinutes\u2192MG, acceptance/cancellation/violations\u2192%).",
  "conditionType": "RideCompleted",
  "conditionOperator": "GTE",
  "conditionValue": 0,
  "rewardType": "NetOffEarnings",
  "rewardValue": 600,
  "evaluation": {
    "logic": {
      "and": [
        {
          ">=": [
            {
              "var": "ridesCompleted"
            },
            0
          ]
        },
        {
          "or": [
            {
              ">=": [
                {
                  "var": "acceptanceRate"
                },
                0
              ]
            },
            {
              ">=": [
                {
                  "var": "onlineMinutes"
                },
                0
              ]
            }
          ]
        }
      ]
    }
  },
  "rewardMetadata": {
    "includeEarningsAllDay": true,
    "mgAmountSlabs": [
      {
        "fromValue": 0,
        "amount": 600
      },
      {
        "fromValue": 60,
        "amount": 800
      },
      {
        "fromValue": 180,
        "amount": 1000
      }
    ],
    "percentSlabs": [
      {
        "metric": "acceptanceRate",
        "slabs": [
          {
            "fromValue": 0,
            "percent": 0
          },
          {
            "fromValue": 50,
            "percent": 50
          },
          {
            "fromValue": 80,
            "percent": 100
          }
        ]
      },
      {
        "metric": "cancellationRate",
        "slabs": [
          {
            "fromValue": 0,
            "percent": 100
          },
          {
            "fromValue": 20,
            "percent": 50
          },
          {
            "fromValue": 50,
            "percent": 0
          }
        ]
      }
    ],
    "violationPercentSlabs": [
      {
        "fromValue": 0,
        "percent": 100
      },
      {
        "fromValue": 1,
        "percent": 50
      },
      {
        "fromValue": 3,
        "percent": 0
      }
    ],
    "violationMetrics": [
      "dxCancel",
      "dafCancel"
    ]
  }
}

{
  "cohortId": "{{ij_mg_cohort_id}}",
  "journeyId": "{{ij_mg_journey_id}}",
  "startDate": "{{_test_start_date}}",
  "streakRange": 2,
  "enabled": true,
  "maxWaiveOffCount": 0,
  "streakEndRewardType": "NetOffEarnings",
  "streakEndRewardValue": 600,
  "streakEndRewardExpirationAt": null,
  "streakEndSubscriptionWaiveOff": null,
  "campaignUserLinkType": "OptIn",
  "controlFeatures": [
    {
      "feature": "CanDxCancelBooking",
      "config": false,
      "enableIn": "AllDay"
    },
    {
      "feature": "AutoAssign",
      "config": {
        "defaultOn": true,
        "allowDriverToToggle": false,
        "disableDriverAreaAndDistancePreference": true
      },
      "enableIn": "AllDay"
    },
    {
      "feature": "PoolingPriority",
      "config": {
        "Default": "HIGH"
      },
      "enableIn": "AllDay"
    }
  ],
  "periodDays": 1,
  "streakEndRewardMetadata": {
    "includeEarningsAllDay": true,
    "mgAmountSlabs": [
      {
        "fromValue": 0,
        "amount": 600
      },
      {
        "fromValue": 60,
        "amount": 800
      },
      {
        "fromValue": 180,
        "amount": 1000
      }
    ],
    "percentSlabs": [
      {
        "metric": "acceptanceRate",
        "slabs": [
          {
            "fromValue": 0,
            "percent": 0
          },
          {
            "fromValue": 50,
            "percent": 50
          },
          {
            "fromValue": 80,
            "percent": 100
          }
        ]
      },
      {
        "metric": "cancellationRate",
        "slabs": [
          {
            "fromValue": 0,
            "percent": 100
          },
          {
            "fromValue": 20,
            "percent": 50
          },
          {
            "fromValue": 50,
            "percent": 0
          }
        ]
      }
    ],
    "violationPercentSlabs": [
      {
        "fromValue": 0,
        "percent": 100
      },
      {
        "fromValue": 1,
        "percent": 50
      },
      {
        "fromValue": 3,
        "percent": 0
      }
    ],
    "violationMetrics": [
      "dxCancel",
      "dafCancel"
    ]
  }
}
